function v20ProjectPanel(){return `<section class="card v20project"><div><span class="v8eyebrow">AI4Climate · ${v20Text('城市暴雨适应','Urban rainfall adaptation')}</span><h2>${v20Text('具体地方，具体的一趟往返','A real place. A complete journey.')}</h2><p>${v20Text('深圳罗湖居民需要的不只是天气：还要知道去程和返程涉及哪些停运区段、易积水地点，以及这些判断依据是什么。','Luohu residents need more than a forecast: service disruptions, flood-prone places and traceable evidence for both legs.')}</p><small>${v20Text('主演示：罗湖 → 深圳人民医院 → 罗湖。就医家庭为体验情境，不是真实患者或求助记录。','Main scenario: Luohu → Shenzhen People’s Hospital → Luohu. The household is a demo scenario, not a real patient record.')}</small></div><div class="v20projectactions"><button class="primary" data-v20="case-history">${v20Text('体验2023年真实公告情境','Try the 2023 notice scenario')}</button><button data-v20="case-now">${v20Text('查看现在的完整往返','Plan a round trip now')}</button><button class="linkbutton" data-v20="ai-evidence">${v20Text('AI做了什么 · 查看验证','AI task and validation')}</button></div></section>`}
function v20AiDialog(){vDialog(v20Text('AI任务、依据与验证','AI task, evidence and validation'),`<p>${v20Text('任务：把公开公告整理成地点、时间、影响区段、方向和信息边界，减少居民反复阅读长公告的负担。','Task: extract locations, times, affected sections, directions and data limits from public notices.')}</p><div class="notice">${v20Text('本版采用AI辅助整理的离线样本，并在制作时逐项对照原文；页面实时关联使用明确规则。没有接通实时生成式AI，也不把数值天气预报或地图称为自研AI。','This edition uses offline AI-assisted samples checked against the source during preparation. Runtime matching uses explicit rules. There is no live generative AI or proprietary weather model.')}</div><h3>${v20Text('真实输入','Real input')}</h3><p>${v20Text('深圳市防汛防旱防风指挥部办公室公告 · 发布','Shenzhen flood-control notice · Published')} ${dateText(V20AI.published)}</p><a href="${V20AI.source}" target="_blank" rel="noopener">${v20Text('阅读完整官方原文','Read the official source')} ↗</a><h3>${v20Text('AI辅助抽取与制作时核对','AI-assisted extraction and source checks')}</h3><div class="tablewrap"><table><tr><th>${v20Text('对象','Object')}</th><th>${v20Text('抽取结果','Extraction')}</th><th>${v20Text('核对位置与边界','Source item and limits')}</th></tr>${V20AI.records.map(r=>`<tr><td data-original>${esc(r.location)}</td><td data-original>${esc(r.category)} · ${esc(r.direction)}</td><td data-original>${esc(r.sourceItem)} · ${esc(r.scope)}；${esc(r.unknown)}</td></tr>`).join('')}</table></div><p>${v20Text('这3项是同一份公告的制作核对样本，不是模型准确率，也不是独立专家评审。核对人：本次制作助手；尚待用户或维护人员独立复核。','These three checks are a production sample from one notice, not an accuracy score or independent expert review. Checked by the preparation assistant; independent review is still pending.')}</p><h3>${v20Text('如何验证是否帮助了居民','How to evaluate usefulness')}</h3><p>${v20Text('对照同一份原始公告和Demo，测试能否找对停运区段、区分长期隐患与现场积水、理解返程限制；记录回答与用时。尚未开展真实用户研究，不预填效率提升或满意度。','Compare the original notice with the demo: can users identify affected sections, distinguish long-term hazards from observations, and understand return constraints? Record answers and time. No user study or improvement claim is prefilled.')}</p><button data-v20="validation-start">${v20Text('开始一次本地体验记录','Start a local evaluation')}</button><button data-v20="ai-download">${v20Text('下载样本与核对清单','Download sample and checklist')}</button>`)}
function v20Validation(){const started=new Date().toISOString();vDialog(v20Text('本地体验记录 · 非真实研究结论','Local evaluation · Not a study result'),`<p>${v20Text('请选择你的实际答案。结果仅保存在本浏览器；可以导出，尚未向研究人员提交。','Enter your actual answers. Results stay in this browser and can be exported; they are not sent to researchers.')}</p><a href="${V20AI.source}" target="_blank" rel="noopener">${v20Text('对照公告原文','Compare with the source')} ↗</a><form id="v20-validation"><input name="started" type="hidden" value="${started}"><label>${v20Text('公告暂停的是哪个区段？','Which section was suspended?')}<select name="section"><option value="">${v20Text('选择答案','Choose an answer')}</option><option value="correct">${v20Text('1号线岗厦—罗湖，两个方向','Line 1 Gangxia–Luohu, both directions')}</option><option value="wrong">${v20Text('全市所有地铁线路','Every metro line in Shenzhen')}</option></select></label><label>${v20Text('长期易积水指引说明什么？','What does a long-term hazard guide tell us?')}<select name="hazard"><option value="">${v20Text('选择答案','Choose an answer')}</option><option value="correct">${v20Text('提示易积水地点，不是当前实测水深','Flood-prone locations, not current water depth')}</option><option value="wrong">${v20Text('证明今天整条路线已积水','The entire route is flooded today')}</option></select></label><label>${v20Text('使用体验与建议（可选）','Comments (optional)')}<textarea name="comment" maxlength="1000"></textarea></label><button class="primary">${v20Text('保存这次实际回答','Save these answers')}</button></form>`)}

const v20EntryBase=v3Entry;v3Entry=function(){return v20EntryBase().replace('每一次出行，<br><span>多一份依据。</span>','暴雨中的一趟往返，<br><span>让判断有依据。</span>').replace('查看罗湖区暴雨出行信息，或进入维护端处理现场反馈。<br>现在只提供两种身份，两边都能以游客方式直接体验。','服务深圳罗湖居民：把公告、天气和地点隐患整理到完整往返中。<br>AI辅助资料整理，公众理解与反馈核验相连接。').replace('公开资料驱动 · 实时信息与共享后端待完善','AI4Climate · 深圳罗湖 · 城市暴雨适应')};
const v20DashboardBase=vDashboard;vDashboard=function(){if(!v11Group().some(p=>p.leg==='return')&&V11.leg==='all')V11.leg='outbound';const h=v20DashboardBase().replace('每一趟出行，多一份依据。','暴雨中的往返，让判断有依据。').replace('填行程、看路径、核对风险，再决定如何出发。','看清两程影响、阅读具体依据，选择适合自己的安排。');return (V20.queryTime?`<div class="notice v20snapshot">${v20Text('正在查看保存的查询：','Saved query: ')}${dateText(V20.queryTime)} · ${v20Text('不是当前实时状态','Not current live conditions')} <button data-v20="live">${v20Text('返回实时查询','Return to live query')}</button></div>`:'')+v20ProjectPanel()+h};
const v20AboutBase=vAbout;vAbout=function(){return v20AboutBase().replace('真实AI与共享反馈待接入','AI辅助资料整理 · 共享后端待接入').replace('当前生成式AI、完整导航、共享后端与交易尚未接入。','使用AI辅助整理的离线公告样本，保留核对证据；实时生成式AI、跨设备共享和交易未接入。')+`<section class="card"><h2>${v20Text('项目与验证','Project and evaluation')}</h2><button data-v20="ai-evidence">${v20Text('查看AI任务、真实资料与验证清单','View AI task, real sources and evaluation checklist')}</button><button data-v20="validation-export">${v20Text('导出本地体验记录','Export local evaluations')}</button></section>`};

function v20Impact(p){const related=vRelated(p),hazards=vRisks(p),reports=vFeedback(p),r=v18RainResult(p);if(p.blocked||related.some(e=>/封闭/.test(e.category)))return {level:'red',title:v20Text('受限：调整此方案','Restricted: change this option'),reason:v20Text('该行程关联已发布的停运或封闭依据。','Published suspension or closure evidence affects this option.'),action:v20Text('取消受限区段的原安排；非必要外出延后，必要事项先远程联系目的地。','Change arrangements for the affected section. Postpone non-essential travel; contact the destination remotely for essential matters.')};if(p.unavailable)return {level:'gray',title:v20Text('路径未取得','Route unavailable'),reason:esc(p.label),action:v20Text('此方案不提供有效时长或通行判断，可改用已收集地点名称或地图选点。','No valid duration or access conclusion is available. Use an indexed place or select a map point.')};if(r.n&&r.percent>=30)return {level:'orange',title:v20Text('强降雨信号较高','Elevated heavy-rain signal'),reason:v20Text('地点集合预报达到较高提示档位。','The location’s ensemble estimate reaches an elevated advisory band.'),action:v18ProbabilityTier(r.percent).advice};if(hazards.length||reports.length||related.some(e=>/积水/.test(e.category)))return {level:'orange',title:v20Text('有影响依据：关注具体地点','Evidence to consider: specific places'),reason:v20Text('已有长期隐患或现场线索关联；它们与实测水深分开显示。','Long-term hazards or observations are related; they remain separate from measured water depth.'),action:v20Text('避开已明确封闭的区段；查看列出的易积水地点，必要时调整途经点。','Avoid confirmed closures, review the listed flood-prone places and adjust via points where needed.')};return {level:'gray',title:v20Text('现场资料有限','Limited field evidence'),reason:v20Text('没有覆盖沿线的积水深度观测。','No standing-water measurements cover this route.'),action:v20Text('当前方案只提供位置与天气参考；没有现场观测不表示通行安全。','This option provides location and weather references. Missing observations do not establish safe access.')};}
function v20DecisionPanel(){const rows=v11Group();return `<section class="v20decisions"><div class="row"><h3>${v20Text('先看出行影响','Travel impact first')}</h3><small>${v20Text('依据分级，不是事故概率','Evidence-based bands, not accident probability')}</small></div>${rows.length?rows.map(p=>{const a=v20Impact(p);return `<article class="v20decision ${a.level}"><b>${p.leg==='return'?v20Text('返程','Return'):v20Text('去程','Outbound')} · ${a.title}</b><p>${a.reason}</p><p>${v20En()?v18English(a.action):a.action}</p></article>`}).join(''):`<p>${v20Text('查询后分别显示两程影响与行动建议。','Query to see the impact and next steps for each leg.')}</p>`}<details><summary>${v20Text('影响等级如何划分？','How are impact bands assigned?')}</summary><p>${v20Text('受限：有对应停运／封闭；关注：关联长期隐患、反馈或较高强降雨信号；资料有限：缺少现场观测；路径未取得：没有有效路线。官方管制优先；这些等级不是校准过的积水或事故概率。','Restricted: matching suspension or closure. Attention: hazards, observations or elevated rain signal. Limited evidence: missing field observations. Route unavailable: no valid route. Official restrictions take precedence; these are not calibrated flooding or accident probabilities.')}</p></details></section>`}
const v20SummaryBase=v8Summary;v8Summary=function(){return v20SummaryBase().replace('</div>','</div>'+v20DecisionPanel())};

// Forecast time is always parsed as Beijing time before selecting an hour.
const v20WeatherDataBase=vWeatherData;vWeatherData=function(){const w=V2.weather;if(V2.mode==='now'&&V20.queryTime&&w)return {temperature:w.current?.temperature_2m,rain:w.current?.precipitation,wind:w.current?.wind_speed_10m,time:w.current?.time,interval:w.current?.interval,label:'保存的模型天气快照'};if(V2.mode==='now'&&V2.departure==='planned'&&w){const hour=V2.planned?v11Local(V2.planned).slice(0,13)+':00':null,i=w.hourly?.time?.indexOf(hour)??-1;return {temperature:i>=0?w.hourly.temperature_2m?.[i]:null,rain:i>=0?w.hourly.precipitation?.[i]:null,prob:i>=0?w.hourly.precipitation_probability?.[i]:null,time:i>=0?w.hourly.time[i]:null,label:'计划出发时段的小时模型天气'}}return v20WeatherDataBase()};
const v20WeatherPanelBase=v8Weather;v8Weather=function(){let h=v20WeatherPanelBase();if(V20.queryTime&&V2.weather?.current?.interval)h=h.replace(/<small>小时降水<\/small>/,`<small>近${Math.round(V2.weather.current.interval/60)}分钟降水</small>`);if(V20.weatherBusy)h=h.replace(/(<button[^>]*(?:data-v5="weather"|data-v2="weather")[^>]*>)[\s\S]*?<\/button>/,'$1正在加载天气…</button>').replace(/<button([^>]*data-v5="weather"[^>]*)>/,'<button$1 disabled aria-busy="true">');return h};
vFetchWeather=async function(){if(V2.mode==='history')return toast('历史模式展示当时公开气象资料。');vDraft();const el=document.getElementById('v5-weather-place');if(el)V5.weatherPlace=el.value;const place=V5.weatherPlace,point=vResolve(place);if(!point)return toast('该地点未取得坐标，可使用已收集地点或地图选点。');const seq=++V20.weatherSeq;V20.weatherBusy=true;V20.queryTime=null;vRender();try{const r=await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${point.lat}&longitude=${point.lon}&current=temperature_2m,precipitation,wind_speed_10m,relative_humidity_2m,apparent_temperature,wind_gusts_10m,wind_direction_10m,surface_pressure,cloud_cover,weather_code&hourly=temperature_2m,precipitation,precipitation_probability,weather_code,relative_humidity_2m,apparent_temperature,wind_speed_10m,wind_gusts_10m&daily=weather_code,temperature_2m_max,temperature_2m_min,precipitation_sum,precipitation_probability_max&forecast_days=7&timezone=Asia%2FShanghai&wind_speed_unit=ms`,{signal:AbortSignal.timeout(15000)});if(!r.ok)throw Error();const w=v26ValidateWeather(await r.json());if(!w.current||!w.hourly)throw Error();if(seq!==V20.weatherSeq||V2.mode!=='now'||place!==V5.weatherPlace)return;V2.weather={...w,place:point.name,fetchedAt:new Date().toISOString()};}catch{if(seq===V20.weatherSeq)toast('天气服务未返回完整数据，原有数据保留并标注原时刻。')}finally{if(seq===V20.weatherSeq){V20.weatherBusy=false;vRender()}}};
const v20AddPlanBase=vAddPlan;vAddPlan=async function(){V20.queryTime=null;await v20AddPlanBase();const group=v11Group();if(V2.mode==='now'&&group.length&&!V2.error){for(const point of new Map(group.map(v18RainLocation).filter(Boolean).map(p=>[v18RainKey(p),p])).values())await v18LoadRain(point);if(!V2.weather)await vFetchWeather();for(const p of group)if(!p.queryWeather&&V2.weather)p.queryWeather=v20Copy(V2.weather);v19CaptureJourneys();vRender()}if(V2.error?.includes('已分别保留两程状态')){V2.error=V5.round?'两程分别保留了查询结果；未取得路径的行程已标明原因，不提供时长或通行判断。':'该方案未取得路径，原因见方案卡；没有有效路径时不提供时长或通行判断。';vRender()}};
const v20RainPanelBase=v18RainPanel;v18RainPanel=function(p){return v20RainPanelBase(p).replace(/（北京时间）(?:（北京时间）)+/g,'（北京时间）')};
const v20RestoreBase=vRestore;vRestore=function(p,compare=false){if(!compare)V20.queryTime=p?.queryTime||p?.created;v20RestoreBase(p,compare);if(!compare&&p){V2.weather=v20Copy(p.queryWeather);V2.at=p.mode==='now'?'':p.at;V2.departure='planned';V2.planned=p.planned?v11Local(p.planned):'';vRender()}};
const v20ResolveBase=vResolve;vResolve=function(text){const p=v20ResolveBase(String(text||''));if(!p||!/^\d+(?:\.\d+)?[,，]/.test(String(text).trim()))return p;const candidates=[...(R10.places||[]),...(D.stations||[])].filter(c=>c.name&&c.lat&&c.lon&&!c.regionOnly);const nearest=candidates.map(c=>({c,d:v10Distance(p,c)})).sort((a,b)=>a.d-b.d)[0];return nearest&&nearest.d<=45?{...p,name:nearest.c.name,coordinate_basis:'输入坐标，关联到约'+Math.round(nearest.d)+'米内公开地点；非入口定位'}:p};
function v20NamedPlan(p){const name=x=>{if(!/^\d+(?:\.\d+)?[,，]/.test(String(x||'').trim()))return x;const q=vResolve(x);return q?.name&&!/^\d/.test(q.name)?q.name.replace(/^深圳市/,'深圳'):x};return {...p,origin:name(p?.origin||V2.origin),destination:name(p?.destination||V2.destination),vias:(p?.vias||V2.vias||[]).map(name)}}
const v20RisksBase=vRisks;vRisks=function(p){return v20RisksBase(v20NamedPlan(p))};
const v20RiskMatchesBase=v12RiskMatches;v12RiskMatches=function(p,r){return v20RiskMatchesBase(v20NamedPlan(p),r)};
const v20HazardsBase=v12Hazards;v12Hazards=function(p){let h=v20HazardsBase(p);const names=[p?.origin,p?.destination].filter(Boolean);if(names.some(n=>/^\d+(?:\.\d+)?[,，]/.test(n))&&!vRisks(p).length)h=h.replace('现有防汛指引尚未收录该地点或道路的专项条款。','此坐标已定位，但没有完成具名地点或道路的资料关联；不能据此判断指引是否收录附近隐患。');return h};

// Compare alternatives only within the same direction, retaining the checkboxes.
v8Compare=function(){const chosen=V2.plans.filter(p=>V2.selected.includes(p.id));const groups=new Map();for(const p of chosen){const key=p.origin+' → '+p.destination;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p)}return `<div class="v8comparechoices">${V2.plans.map((p,i)=>`<label><input type="checkbox" data-plan="${p.id}" ${V2.selected.includes(p.id)?'checked':''}>${v20Text('方案','Option ')}${i+1} · ${esc(p.transport)} · ${p.leg==='return'?v20Text('返程','Return'):v20Text('去程','Outbound')}</label>`).join('')}</div>${[...groups].map(([direction,ps])=>`<h3>${esc(direction)}</h3><div class="tablewrap"><table><tr><th>${v20Text('方案','Option')}</th><th>${v20Text('参考时长','Reference duration')}</th><th>${v20Text('距离','Distance')}</th><th>${v20Text('影响依据','Impact evidence')}</th></tr>${ps.map(p=>`<tr><td>${esc(p.transport)}</td><td>${p.duration!=null?Math.ceil(p.duration/60)+' '+v20Text('分钟','min'):v20Text('未取得','Unavailable')}</td><td>${p.distance!=null?(p.distance/1000).toFixed(1)+' km':'—'}</td><td>${v20Impact(p).title}</td></tr>`).join('')}</table></div>`).join('')||`<p>${v20Text('勾选方案后分方向比较。','Select options to compare by direction.')}</p>`}<button data-v5="report" data-value="方案比较">${v20Text('导出比较报告','Export comparison')} ↗</button>`};

